// =====================================================================
// FLOW A – Mollie-Scan. Rein lesend, erzeugt nur eine CSV.
// Etappenweise: pro Lauf ein Zeitabschnitt, dann 'scanFortsetzenAb'
// aus dem Ergebnis in 'scanStartUrl' eintragen und erneut starten.
// =====================================================================
const CONFIG = {
  mollieBasisUrl: 'https://api.mollie.com/v2',
  scanProSeite:   250,      // Maximum der Orders API
  scanMaxSeiten: 200,      // klein halten! Jede Seite ~900 KB Rohdaten
  scanSortierung: 'desc',   // neueste zuerst

  // Abbruch, sobald eine Seite nur noch aeltere Orders enthaelt.
  scanAbbruchAelterAls: '2026-01-01',


  // Fortsetzung: 'scanFortsetzenAb' aus dem letzten Lauf hier eintragen.
  scanStartUrl: '',

  scanStatus: ['authorized', 'shipping'],
  nurBestellnummern: [],
  testLimit: 0
};
return [{ json: { config: CONFIG } }];

// PHASE 1 – Startpunkt des Mollie-Scans.
//
// SPEICHER: Die Trefferliste liegt NICHT im Item, sondern im Workflow-
// Speicher. Sonst waechst das Item mit jeder Seite, wird bei jeder
// Iteration kopiert, und n8n haelt Ein- UND Ausgabe jeder Iteration vor
// -> quadratischer Verbrauch. Bei 40+ Seiten reisst das die Ausfuehrung ab.
const config = $('Config').first().json.config;

const speicher = $getWorkflowStaticData('global');
speicher.scanTreffer = [];      // bei jedem Lauf frisch
speicher.scanGesehen = 0;

return [{ json: {
  naechsteUrl: config.scanStartUrl ||
    (config.mollieBasisUrl + '/orders?limit=' + config.scanProSeite +
     '&sort=' + config.scanSortierung),
  seite: 0
}}];

// PHASE 1 – Eine Seite auswerten.
//
// Treffer wandern in den Workflow-Speicher, das Item bleibt winzig
// (nur naechsteUrl + Zaehler). Dadurch bleibt der Speicherbedarf konstant,
// statt mit jeder Seite zu wachsen.
const config   = $('Config').first().json.config;
const speicher = $getWorkflowStaticData('global');
// Die Antwort kommt als BINAERDATEI (responseFormat=file). Sie liegt damit
// im Dateisystem statt im Arbeitsspeicher – bei ~900 KB je Seite und vielen
// Seiten ist das der Unterschied zwischen laeuft und stuerzt ab.
let resp = null, parseFehler = null;
try {
  const puffer = await this.helpers.getBinaryDataBuffer(0, 'seite');
  resp = JSON.parse(puffer.toString('utf8'));
} catch (e) {
  // Rueckfallebene, falls doch JSON statt Datei ankommt
  const roh = $input.first().json;
  if (typeof roh?.data === 'string') {
    try { resp = JSON.parse(roh.data); } catch (e2) { parseFehler = e2.message; }
  } else if (roh && typeof roh === 'object' && roh._embedded) {
    resp = roh;
  } else {
    parseFehler = 'Antwort nicht lesbar: ' + e.message;
  }
}

const seite = ($('Scan: Seite auswerten').isExecuted
  ? ($('Scan: Seite auswerten').first().json.seite || 0) : 0) + 1;

if (parseFehler || typeof resp?.status === 'number' || resp?.detail) {
  return [{ json: { seite, naechsteUrl: null, abbruchGrund: 'Fehler',
    gesehen: speicher.scanGesehen || 0,
    treffer: (speicher.scanTreffer || []).length,
    fehler: parseFehler || [resp?.status, resp?.title, resp?.detail]
      .filter(Boolean).join(' – ') }}];
}

const orders  = resp?._embedded?.orders ?? [];
const gesucht = config.scanStatus || ['authorized'];
const geld    = v => (v && v.value !== undefined) ? Number(v.value) : null;

// SCHLANK: nur was spaeter wirklich gebraucht wird.
let neue = 0;
for (const o of orders) {
  if (!gesucht.includes(o?.status)) continue;
  const lines = Array.isArray(o.lines) ? o.lines : [];
  speicher.scanTreffer.push({
    mollieId:      o.id,
    // Der JTL-Bezug steckt nur hier – NICHT in tZahlung.
    bestellnummer: String(o.metadata?.order_number ?? o.orderNumber ?? ''),
    status:        o.status,
    betrag:        geld(o.amount),
    erfasst:       geld(o.amountCaptured),
    expiresAt:     o.expiresAt ?? null,
    versendbar:    lines.reduce((s, l) => s + (Number(l.shippableQuantity) || 0), 0)
  });
  neue++;
}

speicher.scanGesehen = (speicher.scanGesehen || 0) + orders.length;

let naechsteUrl = resp?._links?.next?.href ?? null;
let grund = null;

if (!naechsteUrl)                       grund = 'letzte Seite erreicht';
else if (seite >= config.scanMaxSeiten) { grund = 'maxSeiten erreicht'; naechsteUrl = null; }
else if (config.scanAbbruchAelterAls && orders.length) {
  const grenze   = new Date(config.scanAbbruchAelterAls).getTime();
  const juengste = Math.max(...orders.map(o => new Date(o.createdAt).getTime() || 0));
  if (juengste < grenze) {
    grund = 'nur noch Orders vor ' + config.scanAbbruchAelterAls;
    naechsteUrl = null;
  }
}

// Item bleibt bewusst klein – die Treffer stehen im Workflow-Speicher.
return [{ json: { seite, naechsteUrl, abbruchGrund: grund,
  gesehen: speicher.scanGesehen,
  treffer: speicher.scanTreffer.length,
  trefferDieseSeite: neue, fehler: null }}];

// PHASE 2 – Kandidatenliste aus dem Workflow-Speicher.
// EIN ITEM JE BESTELLUNG, sortiert nach Verfallsfrist: AELTESTE ZUERST.
const config   = $('Config').first().json.config;
const speicher = $getWorkflowStaticData('global');
const s        = $input.first().json;

let treffer = (speicher.scanTreffer || []).filter(t => t.bestellnummer);

// Doppelte Bestellnummern zusammenfuehren
const proNr = new Map();
for (const t of treffer) if (!proNr.has(t.bestellnummer)) proNr.set(t.bestellnummer, t);
treffer = [...proNr.values()];

const weiss = (config.nurBestellnummern || [])
  .map(v => String(v ?? '').trim()).filter(Boolean);
if (weiss.length) {
  const ok = new Set(weiss);
  treffer = treffer.filter(t => ok.has(t.bestellnummer));
}

// Faellige zuerst
treffer.sort((a, b) =>
  String(a.expiresAt ?? '9999').localeCompare(String(b.expiresAt ?? '9999')));

if (config.testLimit > 0) treffer = treffer.slice(0, config.testLimit);

const tage = v => v ? Math.floor((new Date(v).getTime() - Date.now()) / 86400000) : null;

// Feldnamen = CSV-Spalten. Flow B liest exakt diese wieder ein.
return treffer.map(t => ({ json: {
  bestellnummer:  t.bestellnummer,
  mollieId:       t.mollieId,
  status:         t.status,
  betrag:         t.betrag,
  erfasst:        t.erfasst,
  expiresAt:      t.expiresAt,
  restfristTage:  tage(t.expiresAt),
  versendbar:     t.versendbar,
  scanSeiten:       s.seite,
  scanGesehen:      s.gesehen,
  scanAbbruch:      s.abbruchGrund,
  scanFortsetzenAb: s.abbruchGrund === 'maxSeiten erreicht' ? s.naechsteUrl : null,
  scanFehler:       s.fehler ?? null,
  runId: $execution.id
}}));

// CSV schreiben – FORMAT IST DIE SCHNITTSTELLE ZU FLOW B.
// Aenderungen hier muessen dort nachgezogen werden.
const SPALTEN = ["bestellnummer", "mollieId", "status", "betrag", "erfasst", "expiresAt", "restfristTage", "versendbar"];
const T = ';';

const zeilen = $input.all().map(i => i.json).filter(z => z && z.bestellnummer);
if (!zeilen.length) return [{ json: { zeilen: 0, hinweis: 'Keine Treffer' } }];

const p2  = n => String(n).padStart(2, '0');
const txt = v => v === null || v === undefined ? ''
  : typeof v === 'number' ? String(v).replace('.', ',') : String(v);
const feld = v => { const s = txt(v);
  return /["\r\n]/.test(s) || s.includes(T) ? '"' + s.replace(/"/g, '""') + '"' : s; };

const csv = '\uFEFF' + [SPALTEN.join(T),
  ...zeilen.map(z => SPALTEN.map(s => feld(z[s])).join(T))].join('\r\n') + '\r\n';

const j = new Date();
const name = 'mollie-kandidaten-' + j.getFullYear() + p2(j.getMonth()+1) + p2(j.getDate()) +
             '-' + p2(j.getHours()) + p2(j.getMinutes()) + '.csv';

const kopf = zeilen[0] || {};
const summe = zeilen.reduce((s, z) => s + (Number(z.betrag) || 0), 0);
const fristen = zeilen.map(z => z.restfristTage).filter(x => x !== null && x !== '');

return [{
  json: {
    dateiname:        name,
    zeilen:           zeilen.length,
    summeEUR:         Math.round(summe * 100) / 100,
    scanSeiten:       kopf.scanSeiten ?? null,
    scanGesehen:      kopf.scanGesehen ?? null,
    scanAbbruch:      kopf.scanAbbruch ?? null,
    scanFortsetzenAb: kopf.scanFortsetzenAb ?? null,
    kuerzesteFrist:   fristen.length ? Math.min(...fristen) : null,
    bereitsAbgelaufen: fristen.filter(x => x < 0).length,
    spalten:          SPALTEN
  },
  binary: { data: {
    data: Buffer.from(csv, 'utf8').toString('base64'),
    mimeType: 'text/csv', fileName: name, fileExtension: 'csv' } }
}];
